const u={ui:{fig:"Fig. 1",title:"Doublure · pas à pas",svgLabel:"Un dessin isométrique pour doubler un sac : la doublure avec une ouverture, l'extérieur glissé dedans, la couture du haut, le retournement par l'ouverture, sa fermeture et la surpiqûre.",prev:"Étape précédente",dot:(e,r)=>e?`Étape ${e} : ${r}`:r,start:"Étapes →",next:"Suivant →",overview:"Vue d'ensemble",stepOf:(e,r)=>`Étape ${e} sur ${r}`,machine:e=>`Machine : ${e.toLowerCase()}`,inThisStep:"Pour cette étape",takeApart:"Démonter",putTogether:"Assembler",replay:"↻ Revoir",parts:"Pièces",allSteps:"Instructions étape par étape",endView:"VUE EN COUPE"},stitches:{straight:"Point droit"},labels:{liningInsideOut:"doublure sur l'envers",opening8:"ouverture 8 cm",outerRightOut:"extérieur sur l'endroit",cm6:"6 cm",strapsBetween:"anses entre les deux",rightSides:"endroit contre endroit",seam05:"couture 0,5 cm",turnThrough:"retourner par l'ouverture",rightSideOut:"sur l'endroit",tuckEdges:"rentrer les bords",stitchEdge:"piquer au ras du bord",pushLining:"rentrer la doublure",pressEdge:"repasser le bord",topstitch1:"surpiqûre à 1 cm"},steps:[{title:"Le sac doublé",text:"L'extérieur et la doublure sont cousus ensemble par le haut, retournés par une ouverture dans la doublure, puis surpiqués. Appuyez sur le sac pour le démonter."},{title:"Coudre la doublure avec une ouverture",text:"Cousez la doublure comme l'extérieur et laissez-la sur l'envers — mais laissez une ouverture de 8 cm en bas d'une couture de côté. C'est par là que vous retournerez le sac.",details:["Cousez la doublure de la même façon que l'extérieur et laissez-la sur l'envers.","Dans une couture de côté, laissez une ouverture : sur le tote bag, elle fait 8 cm, en bas, juste au-dessus du fond.","L'ouverture peut avoir n'importe quelle longueur, du moment que le sac y passe. Un ouvrage rigide demande plus de place : la panière en tissu, aux parois entoilées, a une ouverture de 15 cm dans une couture d'angle."]},{title:"Glisser l'extérieur dans la doublure",text:"Retournez l'extérieur sur l'endroit et glissez-le dans la doublure restée sur l'envers, endroit contre endroit. Les anses se trouvent entre les deux, épinglées à 6 cm du milieu.",details:["Retournez l'extérieur sur l'endroit ; la doublure reste sur l'envers.","Sur le tote bag, épinglez d'abord les anses sur le bord supérieur de l'extérieur : extrémités au ras du bord, à 6 cm du milieu, les boucles retombant sur le sac.","Glissez l'extérieur dans la doublure pour que les endroits soient face à face et que les anses soient prises entre les deux. Alignez les coutures de côté et les bords supérieurs, puis maintenez-les avec des pinces."]},{title:"Coudre le haut",text:"Cousez tout autour du haut, à 0,5 cm du bord, à travers la doublure, les anses et l'extérieur.",details:["Cousez tout autour du haut, à 0,5 cm du bord, à travers toutes les épaisseurs : la doublure, les anses et l'extérieur.","Le tote bag et la panière ont ici la même couture : 0,5 cm."]},{title:"Retourner par l'ouverture",text:"Passez la main par l'ouverture de la doublure et tirez tout le sac à travers. L'extérieur sort sur l'endroit, la doublure dépasse au-dessus.",details:["Passez la main par l'ouverture de la doublure, attrapez l'extérieur et tirez tout le sac à travers.","Lissez l'extérieur : il est maintenant sur l'endroit. La doublure, elle aussi sur l'endroit, dépasse au-dessus du sac, et son ouverture n'est pas encore fermée."]},{title:"Fermer l'ouverture",text:"Rentrez les bords de l'ouverture le long de la ligne de couture et fermez-la à la machine, au ras du bord. Ou fermez-la à la main, au point invisible.",details:["Rentrez les bords bruts de l'ouverture vers l'intérieur, dans l'alignement du reste de la couture, pour que les deux plis se rejoignent.","Première façon, à la machine : piquez les deux plis ensemble au ras du bord. C'est ainsi que sont fermés le tote bag et la panière ; la couture disparaît ensuite dans le sac.","Deuxième façon, à la main, au point invisible (point d'échelle) : repassez les deux plis, enfilez l'aiguille avec un fil de la couleur du tissu et cachez le nœud dans un pli.","Faites un petit point à l'intérieur d'un pli, puis, juste en face, un petit point à l'intérieur de l'autre. Continuez ainsi d'un côté à l'autre : les fils entre les plis ressemblent aux barreaux d'une échelle.","Régulièrement, après quelques points, tirez sur le fil : les bords se referment et les points disparaissent. À la fin, arrêtez le fil et cachez son extrémité dans la doublure."]},{title:"Rentrer la doublure",text:"Poussez la doublure dans le sac et repassez le bord supérieur bien à plat.",details:["Poussez la doublure dans l'extérieur, jusqu'au fond.","Sur le tote bag, repassez le bord supérieur bien à plat. Dans la panière, lissez la doublure dans les coins."]},{title:"Surpiquer le haut",text:"Surpiquez tout autour du haut, à 1 cm du bord. Sur la panière, la surpiqûre est à 0,5 cm du bord.",details:["Surpiquez tout autour du haut, à travers l'extérieur et la doublure : à 1 cm du bord sur le tote bag, à 0,5 cm sur la panière.","Votre sac est terminé !"]}],legend:[{title:"Extérieur",text:"sur l'endroit · sur le tote bag, les anses sont prises dans son bord supérieur, à 6 cm du milieu"},{title:"Doublure",text:"cousue comme l'extérieur, laissée sur l'envers, puis retournée et rentrée dans le sac"},{title:"Ouverture",text:"dans une couture de la doublure : 8 cm dans une couture de côté du tote bag, 15 cm dans une couture d'angle de la panière · fermée au ras du bord"},{title:"Couture du haut",text:"extérieur et doublure endroit contre endroit, à 0,5 cm du bord"},{title:"Surpiqûre",text:"à 1 cm du bord supérieur sur le tote bag, à 0,5 cm sur la panière"}]};export{u as default};
